-- =====================================================================================
-- ORGANIGRAMA INSTITUCIONAL -> esquema dwsge
-- Fuente : ORGANIGRAMA_2016_18 Modificatoria.vsdx (jerarquia leida de los conectores del Visio)
-- Destino: PostgreSQL, base DW_ESTADISTICA, esquema dwsge
--
-- Objetos:
--   dwsge.dim_tipo_organo        catalogo de categorias del grafico (Alta Direccion, Apoyo, ...)
--   dwsge.dim_tipo_unidad        catalogo de tipos de unidad (Gerencia Central, Subgerencia, ...)
--   dwsge.organigrama_unidad     arbol de unidades (auto-referencia por id_unidad_padre)
--   dwsge.vw_organigrama_jerarquia  vista recursiva con ruta completa de cada unidad
--
-- Es NO destructivo e idempotente: usa CREATE ... IF NOT EXISTS e INSERT ... ON CONFLICT DO NOTHING.
-- Ejecucion:  psql -h <host> -U <user> -d DW_ESTADISTICA -v ON_ERROR_STOP=1 -f organigrama_dwsge.sql
-- =====================================================================================
SET client_encoding = 'UTF8';

BEGIN;

CREATE SCHEMA IF NOT EXISTS dwsge;

-- ---------------------------------------------------------------- catalogos
CREATE TABLE IF NOT EXISTS dwsge.dim_tipo_organo (
    id_tipo_organo  smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo          varchar(20)  NOT NULL UNIQUE,
    nombre          varchar(100) NOT NULL,
    orden           smallint     NOT NULL
);
COMMENT ON TABLE dwsge.dim_tipo_organo IS 'Categorías de órganos según la leyenda del organigrama institucional.';

CREATE TABLE IF NOT EXISTS dwsge.dim_tipo_unidad (
    id_tipo_unidad  smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo          varchar(30)  NOT NULL UNIQUE,
    nombre          varchar(100) NOT NULL
);
COMMENT ON TABLE dwsge.dim_tipo_unidad IS 'Tipos de unidad orgánica (Gerencia Central, Gerencia, Subgerencia, Oficina, ...).';

-- ---------------------------------------------------------------- tabla jerarquica
CREATE TABLE IF NOT EXISTS dwsge.organigrama_unidad (
    id_unidad            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo               varchar(60)  NOT NULL UNIQUE,
    nombre               varchar(250) NOT NULL,
    id_tipo_organo       smallint     NOT NULL REFERENCES dwsge.dim_tipo_organo (id_tipo_organo),
    id_tipo_unidad       smallint     NOT NULL REFERENCES dwsge.dim_tipo_unidad (id_tipo_unidad),
    id_unidad_padre      integer      REFERENCES dwsge.organigrama_unidad (id_unidad),
    tipo_relacion        varchar(15)  NOT NULL DEFAULT 'LINEAL',
    nivel                smallint     NOT NULL,
    orden                smallint     NOT NULL,
    ruta_jerarquica      text         NOT NULL,
    vigente              boolean      NOT NULL DEFAULT true,
    requiere_validacion  boolean      NOT NULL DEFAULT false,
    nota                 text,
    fuente               varchar(100) NOT NULL DEFAULT 'ORGANIGRAMA_2016_18 Modificatoria',
    fecha_carga          timestamp    NOT NULL DEFAULT now(),
    CONSTRAINT ck_organigrama_tipo_relacion CHECK (tipo_relacion IN ('LINEAL', 'DESCONCENTRADA')),
    CONSTRAINT ck_organigrama_nivel         CHECK (nivel >= 1),
    CONSTRAINT ck_organigrama_padre_distinto CHECK (id_unidad_padre IS NULL OR id_unidad_padre <> id_unidad)
);
COMMENT ON TABLE  dwsge.organigrama_unidad IS 'Unidades orgánicas del organigrama institucional. Jerarquía por id_unidad_padre.';
COMMENT ON COLUMN dwsge.organigrama_unidad.codigo IS 'Código jerárquico por posición en el gráfico: 01 = raíz, 01.01 = primer hijo, etc.';
COMMENT ON COLUMN dwsge.organigrama_unidad.tipo_relacion IS 'LINEAL = línea continua; DESCONCENTRADA = enlace en zigzag hacia un órgano desconcentrado.';
COMMENT ON COLUMN dwsge.organigrama_unidad.ruta_jerarquica IS 'Nombres desde la raíz hasta la unidad, separados por " > ".';
COMMENT ON COLUMN dwsge.organigrama_unidad.requiere_validacion IS 'true si la clasificación o el padre se infirió por posición y conviene confirmarlo (ver nota).';

CREATE INDEX IF NOT EXISTS ix_organigrama_unidad_padre       ON dwsge.organigrama_unidad (id_unidad_padre);
CREATE INDEX IF NOT EXISTS ix_organigrama_unidad_tipo_organo ON dwsge.organigrama_unidad (id_tipo_organo);
CREATE INDEX IF NOT EXISTS ix_organigrama_unidad_tipo_unidad ON dwsge.organigrama_unidad (id_tipo_unidad);
CREATE INDEX IF NOT EXISTS ix_organigrama_unidad_codigo_pref ON dwsge.organigrama_unidad (codigo text_pattern_ops);
CREATE UNIQUE INDEX IF NOT EXISTS ux_organigrama_unidad_padre_nombre
    ON dwsge.organigrama_unidad (COALESCE(id_unidad_padre, 0), nombre);

-- ---------------------------------------------------------------- vista recursiva
CREATE OR REPLACE VIEW dwsge.vw_organigrama_jerarquia AS
WITH RECURSIVE arbol AS (
    SELECT u.id_unidad,
           1                          AS nivel_calc,
           ARRAY[u.id_unidad]         AS ruta_ids,
           ARRAY[u.orden::int]        AS ruta_orden,
           u.nombre::text             AS ruta_nombres
    FROM   dwsge.organigrama_unidad u
    WHERE  u.id_unidad_padre IS NULL
    UNION ALL
    SELECT h.id_unidad,
           a.nivel_calc + 1,
           a.ruta_ids || h.id_unidad,
           a.ruta_orden || h.orden::int,
           a.ruta_nombres || ' > ' || h.nombre
    FROM   dwsge.organigrama_unidad h
    JOIN   arbol a ON h.id_unidad_padre = a.id_unidad
    WHERE  NOT h.id_unidad = ANY (a.ruta_ids)          -- proteccion ante ciclos
)
SELECT u.id_unidad,
       u.codigo,
       u.nombre,
       a.nivel_calc                  AS nivel,
       u.id_unidad_padre,
       p.codigo                      AS codigo_padre,
       p.nombre                      AS nombre_padre,
       o.nombre                      AS tipo_organo,
       t.nombre                      AS tipo_unidad,
       u.tipo_relacion,
       u.orden,
       NOT EXISTS (SELECT 1 FROM dwsge.organigrama_unidad x WHERE x.id_unidad_padre = u.id_unidad) AS es_hoja,
       a.ruta_nombres                AS ruta_jerarquica,
       a.ruta_ids,
       a.ruta_orden,
       u.vigente,
       u.requiere_validacion,
       u.nota
FROM   arbol a
JOIN   dwsge.organigrama_unidad u ON u.id_unidad = a.id_unidad
JOIN   dwsge.dim_tipo_organo   o ON o.id_tipo_organo = u.id_tipo_organo
JOIN   dwsge.dim_tipo_unidad   t ON t.id_tipo_unidad = u.id_tipo_unidad
LEFT JOIN dwsge.organigrama_unidad p ON p.id_unidad = u.id_unidad_padre;
COMMENT ON VIEW dwsge.vw_organigrama_jerarquia IS 'Organigrama aplanado con nivel, padre, tipos y ruta completa. Ordenar por ruta_orden para el orden del gráfico.';

-- ---------------------------------------------------------------- carga de catalogos
ON CONFLICT (codigo) DO NOTHING;

ON CONFLICT (codigo) DO NOTHING;

-- ---------------------------------------------------------------- carga de unidades (staging + por niveles)
DROP TABLE IF EXISTS _stg_organigrama;
CREATE TEMP TABLE _stg_organigrama (
    codigo              varchar(60),
    nombre              varchar(250),
    cod_tipo_organo     varchar(20),
    cod_tipo_unidad     varchar(30),
    codigo_padre        varchar(60),
    tipo_relacion       varchar(15),
    nivel               smallint,
    orden               smallint,
    ruta_jerarquica     text,
    requiere_validacion boolean,
    nota                text
);


DO $$
DECLARE
    v_nivel integer;
    v_max   integer;
BEGIN
    SELECT max(nivel) INTO v_max FROM _stg_organigrama;
    FOR v_nivel IN 1 .. v_max LOOP
             nivel, orden, ruta_jerarquica, requiere_validacion, nota)
        SELECT s.codigo, s.nombre, o.id_tipo_organo, t.id_tipo_unidad, p.id_unidad, s.tipo_relacion,
               s.nivel, s.orden, s.ruta_jerarquica, s.requiere_validacion, s.nota
        FROM   _stg_organigrama s
        JOIN   dwsge.dim_tipo_organo o ON o.codigo = s.cod_tipo_organo
        JOIN   dwsge.dim_tipo_unidad t ON t.codigo = s.cod_tipo_unidad
        LEFT JOIN dwsge.organigrama_unidad p ON p.codigo = s.codigo_padre
        WHERE  s.nivel = v_nivel
        ON CONFLICT (codigo) DO NOTHING;
    END LOOP;
END $$;

DROP TABLE IF EXISTS _stg_organigrama;

COMMIT;
